```python
import json

seen = {}

def execute(name: str, args: dict, step: int) -> str:
    key = name + json.dumps(args, sort_keys=True)
    if key in seen:
        return (f"NOTE: you already made this exact call at step {seen[key]} and the result is above. "
                "Use that result, or try something different (for example read_file with offset, or grep).")
    seen[key] = step
    return TOOLS[name](**args)
```

